import urllib.request as u, urllib.error as e, json, time
from datetime import datetime, timezone
B="http://localhost:8080"; tok=None
def get(p):
    global tok
    for i in range(200):
        try:
            if tok is None:
                tok=json.load(u.urlopen(u.Request(B+"/token",method="POST")))["token"]
            return json.load(u.urlopen(u.Request(B+p,headers={"Authorization":"Bearer "+tok})))
        except e.HTTPError as x:
            body=x.read()[:200]
            if x.code==404: return None
            if x.code==401: tok=None; continue
            w=x.headers.get("Retry-After")
            try: w=float(w)
            except: 
                try: w=float(json.loads(body).get("retry_after"))
                except: w=1
            print("err",x.code,body,w); 
            if x.code not in(429,503) and x.code<500: tok=None
            time.sleep(w)
        except Exception as x: print("exc",x); time.sleep(1)
    raise SystemExit("fail "+p)
seen={};dups=0;p=1
while p:
    d=get(f"/orders?page={p}")
    for o in d["items"]:
        if o["id"] in seen:
            dups+=1
            if seen[o["id"]]!=o: print("DIFF",o,seen[o["id"]])
        else: seen[o["id"]]=o
    p=int(d["next"].split("=")[-1]) if d["next"] else 0
print(len(seen),dups,d["total_pages"])
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};R={"north":0,"south":0,"east":0,"west":0};n=0
for o in seen.values():
    if o["status"]!="shipped": continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: print("naive",o)
    if not(lo<=t<hi): continue
    c=o["customer_id"]
    if c not in cust: cust[c]=get("/customers/"+c)
    if cust[c] is None: print("missing cust",o); continue
    a=o["amount_cents"]*(100-cust[c]["discount_pct"])
    R[cust[c]["region"]]+=(a+50)//100; n+=1
r={"total_cents":sum(R.values()),"order_count":n,"duplicates_skipped":dups,"by_region":R}
json.dump(r,open("/workspace/result.json","w"),indent=2);print(r)
